// ==========================================
// Resume Builder: Directory + Fragment Writer
// ==========================================

const fs = require("fs");
const path = require("path");

// ------------------------------
// Configuration
// ------------------------------

const TEMPLATE_PATH = "/PATH/TO/RESUME_SYSTEM_ROOT/templates"; // adjust if needed
const buildPath = $json.build_path;

// ------------------------------
// Safety checks
// ------------------------------

if (!buildPath) {
  throw new Error("build_path missing from workflow input.");
}

if (!fs.existsSync(TEMPLATE_PATH)) {
  throw new Error(`Template folder not found: ${TEMPLATE_PATH}`);
}

// ------------------------------
// Load Inputs
// ------------------------------

const professionalBullets = $json.professional_bullets || [];
const trainingBullets = $json.training_bullets || [];
const skills = $json.skills || {};

// ------------------------------
// Latex Escape Helper
// ------------------------------

function escapeLatex(text) {

  return String(text)
    .replace(/&/g, "\\&")
    .replace(/%/g, "\\%")
    .replace(/\$/g, "\\$")
    .replace(/#/g, "\\#")
    .replace(/_/g, "\\_");

}

// ------------------------------
// Convert bullets → latex items
// ------------------------------

function bulletsToLatex(list) {

  return list
    .filter(Boolean)
    .map(b => `\\item ${escapeLatex(b)}`)
    .join("\n");

}

// ------------------------------
// Convert skills → tabular rows
// ------------------------------

function skillsToLatex(skillObject) {

  const rows = [];

  for (const category in skillObject) {

    const items = skillObject[category] || [];

    const row =
      `\\small \\textbf{${escapeLatex(category)}}: ${items.map(escapeLatex).join(", ")}\\\\`;

    rows.push(row);

  }

  return rows.join("\n");

}

// ------------------------------
// Build fragments
// ------------------------------

const professional_tex = bulletsToLatex(professionalBullets);
const training_tex = bulletsToLatex(trainingBullets);
const skills_tex = skillsToLatex(skills);

// ------------------------------
// Clean previous build (safe)
// ------------------------------

if (fs.existsSync(buildPath)) {
  fs.rmSync(buildPath, { recursive: true, force: true });
}

// ------------------------------
// Create build directory
// ------------------------------

fs.mkdirSync(buildPath, { recursive: true });

// ------------------------------
// Copy LaTeX template
// ------------------------------

fs.cpSync(TEMPLATE_PATH, buildPath, {
  recursive: true
});

// ------------------------------
// Ensure generated directory
// ------------------------------

const generatedDir = path.join(buildPath, "generated");

fs.mkdirSync(generatedDir, { recursive: true });

// ------------------------------
// Write fragment files
// ------------------------------

const files = {
  "professional.tex": professional_tex,
  "training.tex": training_tex,
  "skills.tex": skills_tex
};

for (const [filename, content] of Object.entries(files)) {

  const filePath = path.join(generatedDir, filename);

  fs.writeFileSync(filePath, content, {
    encoding: "utf8"
  });

}

// ------------------------------
// Return updated item
// ------------------------------

return {
  json: {
    ...$json,
    professional_tex,
    training_tex,
    skills_tex,

  }
};

const fs = require("fs");

const build = $("Node1_fragment_builder").first().json;

const pdfPath = `${build.build_path}/main.pdf`;
const logPath = `${build.build_path}/main.log`;

let status = true;
let errors = [];


// ---- check PDF exists ----

if (!fs.existsSync(pdfPath)) {

  status = false;
  errors.push("PDF not generated");

}


// ---- check file size ----

if (status === true) {

  const size = fs.statSync(pdfPath).size;

  if (size < 2000) {
    status = false;
    errors.push("PDF too small, likely compile failure");
  }

}


// ---- check LaTeX log ----

if (fs.existsSync(logPath)) {

  const log = fs.readFileSync(logPath,"utf8");

  if (
    log.includes("! LaTeX Error") ||
    log.includes("Emergency stop") ||
    log.includes("Fatal error")
  ) {
    status = false;
    errors.push("LaTeX compilation error detected");
  }

}


return {
  json: {

    job_page_id: build.job_page_id,

    build_id: build.build_id,

    pdf_path: pdfPath,

    build_path: `${build.build_path}`,

    build_status: status,

    compile_errors: errors

  }
};

